const fs=require("fs");
const path=require("path");
const steps=fs.readFileSync("features/support/steps.js","utf8");
const app=fs.readFileSync("js/app.js","utf8");

// step patterns from steps.js
const patterns=[];
const strRe=/(Given|When|Then)\(\s*([`"\x27])((?:\\\2|(?!\2).)*)\2/g; let m;
while((m=strRe.exec(steps))) patterns.push(m[3]);

// scenario steps from features
function ceToRegex(p){
  // escape regex specials except our {string} token
  let s=p.replace(/[.*+?^${}()|[\]\\]/g,(c)=>c==="{"||c==="}"?"\u0000"+c+"\u0000":("\\"+c));
  s=s.replace(/\u0000\{string\}\u0000/g,"\"[^\"]*\"");
  return new RegExp("^"+s+"$");
}
const matchers=patterns.filter(p=>!p.includes("regex")).map(p=>({p,r:ceToRegex(p)}));
const feats=fs.readdirSync("features").filter(f=>f.endsWith(".feature"));
let used=new Set(); let total=0;
for(const f of feats){
  const lines=fs.readFileSync(path.join("features",f),"utf8").split("\n");
  for(let ln of lines){
    const t=ln.trim();
    if(/^(Given|When|Then|And|But)\s+/.test(t)){
      const text=t.replace(/^(Given|When|Then|And|But)\s+/,"");
      total++;
      for(const mt of matchers){ if(mt.r.test(text)){ used.add(mt.p); break; } }
    }
  }
}
const orphan=patterns.filter(p=>!used.has(p));
console.log("scenario steps parsed:",total);
console.log("step defs:",patterns.length,"used:",used.size);
console.log("orphaned step defs:",orphan.length?orphan:"none");
